```javascript
class TodoModel {
    constructor() {
        this.todos = [];
    }

    addTodo(text) {
        this.todos.push({ id: Date.now(), text, completed: false });
    }

    removeTodo(id) {
        this.todos = this.todos.filter(todo => todo.id !== id);
    }

    toggleTodo(id) {
        this.todos = this.todos.map(todo =>
            todo.id === id ? { ...todo, completed: !todo.completed } : todo
        );
    }

    getTodos() {
        return this.todos;
    }
}
```

